2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"io"
8		"net/http"
9		"net/http/httptest"
10		"net/url"
11		"strconv"
12		"strings"
13	
14		"github.com/labstack/echo/v5"
15		sdkmcp "github.com/modelcontextprotocol/go-sdk/mcp"
16		"github.com/pkg/errors"
17	)
18	
19	type apiAdapter struct {
20		echoServer *echo.Echo
21	}
22	
23	func newAPIAdapter(echoServer *echo.Echo) *apiAdapter {
24		return &apiAdapter{echoServer: echoServer}
25	}
26	
27	func (a *apiAdapter) execute(ctx context.Context, operation *openAPIOperation, arguments map[string]any, authorization string) (*sdkmcp.CallToolResult, error) {
28		req, err := buildAPIRequest(ctx, operation, arguments, authorization)
29		if err != nil {
30			return newToolErrorResult(err.Error()), nil
31		}
32	
33		recorder := httptest.NewRecorder()
34		a.echoServer.ServeHTTP(recorder, req)
35	
36		value, err := decodeJSONValue(recorder.Body.Bytes())
37		if err != nil {
38			return newToolErrorResult(err.Error()), nil
39		}
40		if recorder.Code < http.StatusOK || recorder.Code >= http.StatusMultipleChoices {
41			return newToolErrorResult(apiErrorMessage(recorder.Code, value)), nil
42		}
43		return newStructuredToolResult(value)
44	}
45	
46	func buildAPIRequest(ctx context.Context, operation *openAPIOperation, arguments map[string]any, authorization string) (*http.Request, error) {
47		path, err := substitutePathParameters(operation, arguments)
48		if err != nil {
49			return nil, err
50		}
51	
52		query := url.Values{}
53		for _, parameter := range operation.Parameters {
54			if parameter.In != "query" {
55				continue
56			}
57			value, ok := arguments[parameter.Name]
58			if !ok || value == nil {
59				continue
60			}
61			query.Set(parameter.Name, valueToString(value))
62		}
63		if encoded := query.Encode(); encoded != "" {
64			path += "?" + encoded
65		}
66	
67		var body io.Reader
68		if operation.RequestBody != nil {
69			bodyValue, ok := arguments["body"]
70			if !ok || bodyValue == nil {
71				if operation.RequestBody.Required {
72					return nil, errors.New(`missing required request body "body"`)
73				}
74				bodyValue = map[string]any{}
75			}
76	
77			data, err := json.Marshal(bodyValue)
78			if err != nil {
79				return nil, errors.Wrap(err, "failed to marshal request body")
80			}
81			body = bytes.NewReader(data)
82		}
83	
84		req := httptest.NewRequest(operation.Method, path, body).WithContext(ctx)
85		if body != nil {
86			req.Header.Set("Content-Type", "application/json")
87		}
88		if authorization != "" {
89			req.Header.Set("Authorization", authorization)
90		}
91		return req, nil
92	}
93	
94	func substitutePathParameters(operation *openAPIOperation, arguments map[string]any) (string, error) {
95		path := operation.Path
96		for _, parameter := range operation.Parameters {
97			if parameter.In != "path" {
98				continue
99			}
100	
101			value, ok := arguments[parameter.Name]
102			if !ok || value == nil || valueToString(value) == "" {
103				return "", errors.Errorf(`missing required path parameter "%s"`, parameter.Name)
104			}
105			path = strings.ReplaceAll(path, "{"+parameter.Name+"}", url.PathEscape(valueToString(value)))
106		}
107		return path, nil
108	}
109	
110	func valueToString(value any) string {
111		switch typed := value.(type) {
112		case string:
113			return typed
114		case bool:
115			return strconv.FormatBool(typed)
116		case int:
117			return strconv.Itoa(typed)
118		case int8:
119			return strconv.FormatInt(int64(typed), 10)
120		case int16:
121			return strconv.FormatInt(int64(typed), 10)
122		case int32:
123			return strconv.FormatInt(int64(typed), 10)
124		case int64:
125			return strconv.FormatInt(typed, 10)
126		case uint:
127			return strconv.FormatUint(uint64(typed), 10)
128		case uint8:
129			return strconv.FormatUint(uint64(typed), 10)
130		case uint16:
131			return strconv.FormatUint(uint64(typed), 10)
132		case uint32:
133			return strconv.FormatUint(uint64(typed), 10)
134		case uint64:
135			return strconv.FormatUint(typed, 10)
136		case float32:
137			return strconv.FormatFloat(float64(typed), 'f', -1, 32)
138		case float64:
139			return strconv.FormatFloat(typed, 'f', -1, 64)
140		default:
141			data, err := json.Marshal(value)
