30	func (c *instanceStatsCache) get() (*v1pb.InstanceStats, bool) {
31		c.mu.Lock()
32		defer c.mu.Unlock()
33		if c.value == nil || time.Now().After(c.expiry) {
34			return nil, false
35		}
36		return c.value, true
37	}
